      /* ================= OP 与标题待机画面 ================= */
      body.prelude-active {
        overflow: hidden;
      }

      .lk-prelude {
        position: fixed;
        inset: 0;
        z-index: 2147483000;
        width: 100%;
        height: 100%;
        max-width: 100%;
        max-height: 100%;
        overflow: hidden;
        color: #fff;
        background: #000;
        container-type: size;
        opacity: 1;
        visibility: visible;
        transition:
          opacity 420ms ease,
          visibility 420ms ease;
      }

      /* SillyTavern 直接挂载时，只占用当前消息块，不覆盖整个酒馆界面。 */
      .lk-prelude-host-active {
        position: relative !important;
        width: 100% !important;
        height: auto !important;
        min-width: 0 !important;
        min-height: 0 !important;
        aspect-ratio: 16 / 9;
        overflow: hidden !important;
        isolation: isolate;
      }

      .lk-prelude.is-message-embedded {
        position: absolute;
        width: 100%;
        height: 100%;
        min-height: 0;
      }

      .lk-prelude.is-finished {
        opacity: 0;
        visibility: hidden;
        pointer-events: none;
      }

      .lk-prelude-screen {
        position: absolute;
        inset: 0;
        display: grid;
        place-items: center;
        container-type: size;
        overflow: hidden;
        visibility: hidden;
        opacity: 0;
        pointer-events: none;
        transition:
          opacity 420ms ease,
          visibility 420ms ease;
      }

      /* 前景舞台承载视频/图片/Logo/提示，所有组件以同一 16:9 基准整体缩放。 */
      .lk-prelude-stage {
        position: relative;
        z-index: 2;
        width: 100%;
        height: auto;
        max-width: 100%;
        max-height: 100%;
        aspect-ratio: 16 / 9;
        overflow: hidden;
        isolation: isolate;
        container-type: size;
        background: #050403;
        box-shadow: 0 0 52px rgba(0, 0, 0, 0.5);
      }

      @supports (width: 1cqw) {
        .lk-prelude-stage {
          width: min(100cqw, calc(100cqh * 1.7777778));
          height: min(100cqh, calc(100cqw * 0.5625));
        }
      }

      .lk-prelude-screen.is-active {
        visibility: visible;
        opacity: 1;
        pointer-events: auto;
      }

      .lk-opening-screen {
        isolation: isolate;
        cursor: pointer;
        background: #100b09;
      }

      .lk-opening-video-backdrop {
        position: absolute;
        inset: -8%;
        z-index: 0;
        width: 116%;
        height: 116%;
        object-fit: cover;
        object-position: center;
        filter: blur(26px) brightness(0.58) saturate(0.82);
        transform: scale(1.08);
        pointer-events: none;
      }

      .lk-opening-screen::before {
        content: "";
        position: absolute;
        inset: 0;
        z-index: 1;
        pointer-events: none;
        background: radial-gradient(
          circle at center,
          rgba(30, 18, 14, 0.04),
          rgba(0, 0, 0, 0.26) 82%
        );
      }

      .lk-opening-video {
        width: 100%;
        height: 100%;
        display: block;
        object-fit: cover;
        object-position: center;
        background: #000;
      }

      .lk-opening-stage::after {
        content: "";
        position: absolute;
        inset: auto 0 0;
        z-index: 2;
        height: 20%;
        pointer-events: none;
        background: linear-gradient(to top, rgba(0, 0, 0, 0.58), transparent);
      }

      .lk-op-sound-gate {
        position: absolute;
        left: 50%;
        top: 50%;
        z-index: 4;
        display: none;
        min-width: min(78vw, 320px);
        min-width: min(78cqw, 320px);
        border: 1px solid rgba(230, 197, 126, 0.78);
        padding: 15px 24px 13px;
        transform: translate(-50%, -50%);
        color: #fff;
        background: rgba(7, 5, 4, 0.76);
        box-shadow:
          0 12px 38px rgba(0, 0, 0, 0.44),
          inset 0 0 0 1px rgba(255, 255, 255, 0.08);
        font-family: Georgia, "Times New Roman", serif;
        font-size: clamp(13px, 1.2vw, 18px);
        font-size: clamp(11px, 1.2cqw, 18px);
        letter-spacing: 0.17em;
        text-align: center;
        cursor: pointer;
        backdrop-filter: blur(8px);
      }

      .lk-op-sound-gate.is-visible {
        display: block;
      }

      .lk-op-sound-gate small {
        display: block;
        margin-top: 7px;
        color: rgba(255, 255, 255, 0.7);
        font-family: "Microsoft YaHei", sans-serif;
        font-size: 11px;
        font-size: clamp(9px, 1cqw, 11px);
        letter-spacing: 0.08em;
      }

      .lk-op-skip {
        position: absolute;
        right: clamp(18px, 3vw, 48px);
        right: clamp(12px, 3cqw, 48px);
        bottom: clamp(16px, 3vh, 38px);
        bottom: clamp(10px, 3cqh, 38px);
        z-index: 4;
        border: 0;
        padding: 8px 0;
        color: rgba(255, 255, 255, 0.82);
        background: transparent;
        font-family: Georgia, "Times New Roman", serif;
        font-size: clamp(10px, 0.85vw, 14px);
        font-size: clamp(9px, 0.85cqw, 14px);
        letter-spacing: 0.24em;
        text-shadow: 0 1px 8px rgba(0, 0, 0, 0.95);
        cursor: pointer;
      }

      .lk-title-screen {
        isolation: isolate;
        cursor: pointer;
        background: #160e0b;
      }

      .lk-title-art {
        position: absolute;
        inset: 0;
        z-index: -3;
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: center;
        user-select: none;
        -webkit-user-drag: none;
      }

      .lk-prelude.is-message-embedded .lk-op-sound-gate {
        min-width: min(78cqw, 320px);
        font-size: clamp(11px, 1.2cqw, 18px);
      }

      .lk-prelude.is-message-embedded .lk-op-skip {
        right: clamp(12px, 3cqw, 48px);
        bottom: clamp(10px, 3cqh, 38px);
        font-size: clamp(9px, 0.85cqw, 14px);
      }

      .lk-prelude.is-message-embedded .lk-title-logo {
        top: clamp(12px, 5cqh, 68px);
        width: min(42cqw, 620px);
        max-height: 25cqh;
      }

      .lk-prelude.is-message-embedded .lk-continue-prompt {
        bottom: clamp(14px, 8cqh, 100px);
        min-width: min(88cqw, 720px);
        padding: clamp(8px, 1.7cqh, 18px) clamp(12px, 2cqw, 26px);
        font-size: clamp(10px, 1.35cqw, 23px);
      }

      .lk-title-screen::before {
        content: "";
        position: absolute;
        inset: -8%;
        z-index: 0;
        pointer-events: none;
        background:
          linear-gradient(rgba(30, 17, 12, 0.2), rgba(8, 5, 4, 0.34)),
          url("https://eriribot.github.io/rakudai-knight/title-screen-8k.png")
            center / cover no-repeat;
        filter: blur(28px) saturate(0.78) brightness(0.78);
        transform: scale(1.08);
      }

      .lk-title-screen::after {
        content: "";
        position: absolute;
        inset: 0;
        z-index: 1;
        pointer-events: none;
        background: radial-gradient(
          circle at center,
          transparent 34%,
          rgba(5, 3, 2, 0.2) 100%
        );
      }

      .lk-title-stage::before,
      .lk-title-stage::after {
        content: "";
        position: absolute;
        inset: 0;
        pointer-events: none;
      }

      .lk-title-stage::before {
        z-index: -2;
        background:
          linear-gradient(to bottom, rgba(10, 8, 7, 0.14), transparent 32%),
          linear-gradient(to top, rgba(9, 6, 5, 0.8), transparent 40%);
      }

      .lk-title-stage::after {
        z-index: -1;
        box-shadow: inset 0 0 14vw rgba(0, 0, 0, 0.3);
        box-shadow: inset 0 0 14cqw rgba(0, 0, 0, 0.3);
      }

      .lk-title-logo {
        position: absolute;
        top: clamp(22px, 5vh, 68px);
        top: clamp(12px, 5cqh, 68px);
        left: 50%;
        width: min(42vw, 620px);
        width: min(42cqw, 620px);
        max-height: 25vh;
        max-height: 25cqh;
        object-fit: contain;
        transform: translateX(-50%);
        filter: drop-shadow(0 2px 1px rgba(255, 255, 255, 0.72))
          drop-shadow(0 5px 13px rgba(0, 0, 0, 0.44));
        user-select: none;
        -webkit-user-drag: none;
      }

      .lk-continue-prompt {
        position: absolute;
        left: 50%;
        bottom: clamp(30px, 8vh, 100px);
        bottom: clamp(14px, 8cqh, 100px);
        min-width: min(88vw, 720px);
        min-width: min(88cqw, 720px);
        border: 0;
        padding: 18px 26px;
        transform: translateX(-50%);
        color: #fff;
        background: transparent;
        font-family: Georgia, "Times New Roman", serif;
        font-size: clamp(13px, 1.35vw, 23px);
        font-size: clamp(10px, 1.35cqw, 23px);
        font-weight: 600;
        letter-spacing: clamp(0.16em, 0.45vw, 0.34em);
        letter-spacing: clamp(0.16em, 0.45cqw, 0.34em);
        text-align: center;
        text-indent: clamp(0.16em, 0.45vw, 0.34em);
        text-indent: clamp(0.16em, 0.45cqw, 0.34em);
        text-shadow:
          0 2px 3px rgba(0, 0, 0, 0.95),
          0 0 14px rgba(0, 0, 0, 0.82);
        cursor: pointer;
        animation: lk-prompt-pulse 1.65s ease-in-out infinite;
      }

      .lk-continue-prompt::before,
      .lk-continue-prompt::after {
        content: "◆";
        display: inline-block;
        margin: 0 1.1em;
        color: #d6b060;
        font-size: 0.55em;
        vertical-align: 0.15em;
      }

      @keyframes lk-prompt-pulse {
        0%,
        100% {
          opacity: 0.42;
        }
        50% {
          opacity: 1;
        }
      }

      @media (max-aspect-ratio: 4 / 5) {
        .lk-title-art {
          object-position: 45% center;
        }

        .lk-title-logo {
          width: min(74vw, 540px);
        }

        .lk-continue-prompt::before,
        .lk-continue-prompt::after {
          display: none;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        .lk-prelude,
        .lk-prelude-screen {
          transition-duration: 1ms;
        }

        .lk-continue-prompt {
