.aw-school::after { content: ""; position: absolute; width: 13px; height: 13px; right: -1px; top: -1px; background: linear-gradient(45deg, transparent 48%, var(--ast-line) 49%, var(--ast-line) 53%, #edf4f6 54%); }
.aw-school:hover:not(:disabled) { background: #f6fafc; border-color: var(--school-mark); box-shadow: 0 3px 12px rgba(30, 63, 78, .08); }
