/* Two original illustrations, preserved without cropping or image edits.
   Load after the world themes. Only the title standby screen is affected.
   Children: .lk-title-art, .aw-title-original-art, .lk-title-logo,
   .aw-title-logo, optional .aw-title-divider/.aw-title-cross, .lk-continue-prompt.
*/
#lkPrelude[data-title-layout="original-pair"] .lk-title-screen {
  container-name: original-pair-title;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  align-items: safe center;
  background: #151b26;
}
#lkPrelude[data-title-layout="original-pair"] .lk-title-screen::before {
  inset: 0;
  background:
    radial-gradient(ellipse at 15% 35%, rgba(134, 55, 62, .25), transparent 60%),
    radial-gradient(ellipse at 85% 35%, rgba(33, 127, 160, .26), transparent 60%),
    #151b26;
  filter: none;
  transform: none;
}
#lkPrelude[data-title-layout="original-pair"] .lk-title-screen::after {
  display: none;
}
#lkPrelude[data-title-layout="original-pair"] .lk-title-stage {
  --pair-gap: clamp(14px, 2cqw, 28px);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  column-gap: var(--pair-gap);
  row-gap: 14px;
  align-items: center;
  box-sizing: border-box;
  width: min(100%, 1600px);
  height: auto;
  min-height: 0;
  max-width: 1600px;
  max-height: none;
  aspect-ratio: auto;
  container-type: normal;
  padding: clamp(14px, 1.6cqw, 26px);
  overflow: visible;
  isolation: isolate;
  background: linear-gradient(90deg, #fff4f1 0%, #fff9f6 49.8%, #f1faff 50.2%, #eaf7fc 100%);
  border: 1px solid rgba(255, 255, 255, .3);
  border-radius: 4px;
  box-shadow: 0 18px 70px rgba(0, 0, 0, .3);
}
#lkPrelude[data-title-layout="original-pair"] .lk-title-stage::before,
#lkPrelude[data-title-layout="original-pair"] .lk-title-stage::after {
  display: none;
}
/* Intrinsic width/height stays authoritative: never crop or stretch a source. */
#lkPrelude[data-title-layout="original-pair"] .lk-title-art,
#lkPrelude[data-title-layout="original-pair"] .aw-title-original-art {
  position: relative;
  inset: auto;
  z-index: 1;
  display: block;
  box-sizing: border-box;
  width: 100%;
  height: auto;
  min-width: 0;
  max-width: 100%;
  max-height: none;
  margin: 0;
  align-self: center;
  object-fit: contain;
  object-position: center;
  aspect-ratio: auto;
  transform: none;
  filter: none;
  opacity: 1;
  clip-path: none;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}
#lkPrelude[data-title-layout="original-pair"] .lk-title-art {
  grid-column: 1;
  grid-row: 2;
}
#lkPrelude[data-title-layout="original-pair"] .aw-title-original-art {
  grid-column: 2;
  grid-row: 2;
}
/* Original PNG logos sit in their own band, outside both illustrations. */
#lkPrelude[data-title-layout="original-pair"] .lk-title-logo,
#lkPrelude[data-title-layout="original-pair"] .aw-title-logo {
  position: relative;
  inset: auto;
  z-index: 2;
  display: block;
  box-sizing: border-box;
  width: min(80%, 350px);
  height: clamp(64px, 7.5cqw, 104px);
  min-width: 0;
  max-width: 100%;
  max-height: none;
  margin: 0 auto;
  object-fit: contain;
  object-position: center;
  transform: none;
  filter: none;
  opacity: 1;
  clip-path: none;
}
#lkPrelude[data-title-layout="original-pair"] .lk-title-logo {
  grid-column: 1;
  grid-row: 1;
