function nextStoryChapterForState(volume, key, state) {
  if (volume === 10 && key === '第二章' && state?.场景?.路线 === 'B') {
    return { volume: 16, chapter: '序章' };
  }
  if (volume === 16 && key === '终章Ⅱ') {
    return { volume: 18, chapter: '第二章' };
  }
  return nextStoryChapter(volume, key);
}

