}

// 默认保留独立 G04 的旧申请接口；字段约束显式使用 final，只校正终值与晋级。
function enforceGrowthProgress(variables, previous, { replyKey = '', repairEventKeys = [], growthFinalAxes = [], growthGradeAxes = [], mode = 'legacy' } = {}) {
  if (resolveMvuWorld(previous?.stat_data) !== 'rakudai') return [];
  const before = previous?.stat_data, after = variables?.stat_data, notices = [];
  if (before?.系统?.结构版本 !== 4 || before.系统.开局状态 !== '已建档' || !after?.玩家) return notices;
  const old = before.玩家.成长, incoming = after.玩家.成长;
  if (!old && incoming === undefined) return notices;
  const finalOnly = mode === 'final';
  const growth = growthState(old, { legacyRequests: !finalOnly }), scoped = typeof replyKey === 'string' && !!replyKey;
  const explicitFinal = new Set(growthFinalAxes), explicitGrades = new Set(growthGradeAxes);
  const correctedExperience = {};
  if (scoped) for (const axis of GROWTH_AXES) {
    const value = incoming?.经验?.[axis];
    // N03 补缺的零初值不是模型提交的经验终值；显式提交零仍可纠错。
    if (Number.isSafeInteger(value) && value >= 0 && (value !== (old?.经验?.[axis] ?? 0) || explicitFinal.has(axis))) correctedExperience[axis] = value;
  }
  const proposed = finalOnly ? {} : normalizeGrowthRequests(growthObject(incoming?.申请) ? incoming.申请 : growth.申请);
  if (!finalOnly) growth.申请 = cloneState(proposed);
  const events = after.场景.已发生事件 || {}, oldEvents = before.场景.已发生事件 || {};
  function note(id, message) { notices.push({ path: finalOnly ? '/玩家/成长' : '/玩家/成长/申请/' + id, message }); growth.最近提示 = message; }
  // 元数据和收据原样继承；经验终值是业务数据，主副 API 都可以明确校正。
  const owned = value => growthObject(value) ? Object.fromEntries(Object.entries(value).filter(([key]) => !(finalOnly ? ['经验'] : ['申请', '经验']).includes(key))) : {};
  if (stateKey(owned(incoming)) !== stateKey(owned(old))) note('结算收据', '版本、历史申请与结算记录由代码维护，本次已保留原数据；其它字段继续更新。');
  const repairEvents = new Set(Array.isArray(repairEventKeys) ? repairEventKeys.filter(growthName) : []);
  const budget = scoped && growth.回合结算?.标识 === replyKey ? cloneState(growth.回合结算) : { 标识: replyKey, 获得: {}, 已晋级: [] };
  for (const axis of GROWTH_AXES) {
    const spent = !finalOnly && scoped ? Object.values(growth.记录).filter(row => row.回合 === replyKey && row.目标 === axis).reduce((sum, row) => sum + row.获得, 0) : 0;
    budget.获得[axis] = Math.min(GROWTH_RULES.perReplyCap, Math.max(budget.获得[axis] || 0, spent));
  }
  const finalInputs = new Map();
  if (scoped) for (const axis of GROWTH_AXES) {
    if (!explicitFinal.has(axis) && !explicitGrades.has(axis)) continue;
    const signature = JSON.stringify([explicitFinal.has(axis) ? incoming?.经验?.[axis] : null, explicitGrades.has(axis) ? after.玩家.六维?.[axis] : null]);
    finalInputs.set(axis, signature);
    const receipt = budget.终值收据?.[axis];
    if (receipt?.提交 === signature && before.玩家.六维?.[axis] === receipt.评级 && old?.经验?.[axis] === receipt.经验) {
      after.玩家.六维[axis] = receipt.评级;
      if (explicitFinal.has(axis)) correctedExperience[axis] = receipt.经验;
    }
  }
  let settled = false;
  for (const [id, request] of Object.entries(proposed)) {
    if (!growthName(id)) { note(id, '申请名称无效，仅保留待修正。'); continue; }
    if (Object.hasOwn(growth.记录, id)) { delete growth.申请[id]; continue; }
    if (!growthRequestValid(request)) {
      if (growthObject(old?.申请) && stateKey(old.申请[id]) === stateKey(request)) continue;
      note(id, '此申请缺少有效来源事件、目标、非负整数经验或成果；多目标与经验数组须逐项对应。已保留待修正，其它更新照常保存。'); continue;
    }
    if (!scoped) { note(id, '尚不能确认真实助手回复，本次保留申请，不猜测来源或扣除额度。'); continue; }
    if (request.目标 === '魔力量' && after.玩家.魔人觉醒 !== true) { note(id, '魔人觉醒不是 true，魔力量申请暂不结算；其它目标照常结算。'); continue; }
    const event = Object.hasOwn(events, request.来源事件) ? events[request.来源事件] : null;
    if (!growthObject(event) || typeof event.结果 !== 'string' || !event.结果.trim()) { note(id, '来源事件结果尚未保存，已保留此申请待补；其它变量照常更新。'); continue; }
    const pos = storyPosition(event.卷号, event.章段), from = storyPosition(before.场景.当前卷, before.场景.当前章);
    if (pos < from - (repairEvents.has(request.来源事件) ? 1 : 0) || pos < 0 || pos > storyPosition(after.场景.当前卷, after.场景.当前章)) {
      note(id, '来源不属于本轮实际经历的章段；保留待核对，不补造跳过的训练。'); continue;
    }
    const fingerprint = growthFingerprint(request, event);
    if (Object.values(growth.记录).some(row => row.目标 === request.目标 && (row.来源事件 === request.来源事件 || row.活动指纹 === fingerprint ||
      oldEvents[row.来源事件] && growthFingerprint(request, oldEvents[row.来源事件]) === fingerprint))) {
      delete growth.申请[id]; note(id, '同一来源成果与目标已经结算，不重复领取。'); continue;
    }
    if (!repairEvents.has(request.来源事件) && String(oldEvents[request.来源事件]?.结果 || '').replace(/\s+/g, '') === event.结果.replace(/\s+/g, '')) {
      note(id, '本轮未新增此来源的实际成果，旧活动不追授经验。'); continue;
    }
    const rank = after.玩家.六维?.[request.目标];
    if (!GROWTH_RULES.costs[rank] && rank !== 'S') { note(id, '此目标评级未知，申请保留待核定；其它目标继续。'); continue; }
    // 经验终值与同源申请同时出现时，以终值为准，并保存零叠加收据防止下次补漏重领。
    const finalProvided = Object.hasOwn(correctedExperience, request.目标);
    const award = !finalProvided && rank !== 'S' ? Math.min(request.经验, Math.max(0, GROWTH_RULES.perReplyCap - budget.获得[request.目标])) : 0;
    growth.经验[request.目标] = Math.min(Number.MAX_SAFE_INTEGER, growth.经验[request.目标] + award);
    budget.获得[request.目标] += award;
    let explanation = request.目标 + ' +' + award + (request.类型 ? '；' + request.类型 : '') + '。';
    if (finalProvided) explanation += ' 本轮已明确经验最终值，此申请记为已处理，不再重复相加。';
    else if (rank === 'S') explanation += ' 已到本卡量表顶档，保留原有余量。';
    else if (award < request.经验) explanation += ' 按本轮此目标合计 ' + GROWTH_RULES.perReplyCap + ' 上限截断，超额不延后补领。';
    growth.记录[id] = { 来源事件: request.来源事件, 目标: request.目标, 类型: request.类型, 方式: request.方式,
      成果: request.成果, 获得: award, 活动指纹: fingerprint, 说明: explanation, 回合: replyKey };
    delete growth.申请[id]; growth.最近提示 = explanation; settled = true;
  }
  Object.assign(growth.经验, correctedExperience);
  // 评级发生明确校正后，经验按该新评级的当前档进度计算；没有新申请也修复旧档溢出。
  const promotions = [];
  if (scoped) for (const axis of GROWTH_AXES) {
    if (axis === '魔力量' && after.玩家.魔人觉醒 !== true) continue;
    const initialRank = after.玩家.六维?.[axis];
    let rank = initialRank, index = ATTRIBUTE_GRADES.indexOf(rank), cost = GROWTH_RULES.costs[rank];
    while (cost && index > 0 && growth.经验[axis] >= cost) {
      growth.经验[axis] -= cost; rank = ATTRIBUTE_GRADES[--index]; cost = GROWTH_RULES.costs[rank];
    }
    if (rank === initialRank) continue;
    after.玩家.六维[axis] = rank;
    if (!budget.已晋级.includes(axis)) budget.已晋级.push(axis);
    const text = axis + '：' + initialRank + ' → ' + rank + '，剩余经验 ' + growth.经验[axis] + '。';
    promotions.push(text);
    const receipt = finalOnly ? null : Object.values(growth.记录).findLast(row => row.回合 === replyKey && row.目标 === axis);
    if (receipt) receipt.说明 += ' ' + text;
  }
  for (const [axis, signature] of finalInputs) {
    if (!ATTRIBUTE_GRADES.includes(after.玩家.六维?.[axis])) continue;
    budget.终值收据 ??= {};
    budget.终值收据[axis] = { 提交: signature, 经验: growth.经验[axis], 评级: after.玩家.六维[axis] };
  }
  if (settled || promotions.length || finalInputs.size) growth.回合结算 = budget;
  if (promotions.length) growth.最近提示 = promotions.join(' ');
  after.玩家.成长 = growth;
  return notices;
}

function editOcPlayerProfile(before, request) {
  if (before.系统?.开局状态 !== '已建档' || before.系统?.主角模式 !== '自定义角色') throw new Error('只有已建档的自定义角色可以编辑个人资料。');
  if (!request || typeof request !== 'object') throw new Error('个人资料操作无效。');
  const state = cloneState(before), player = state.玩家;
  const text = (value, label) => {
    if (typeof value !== 'string') throw new Error(`${label}必须是文字。`);
    return value;
  };
  if (request.action === 'bio') {
    player.角色简介 = text(request.bio, '角色简介');
  } else if (request.action === 'ability') {
    if (resolveMvuWorld(before) === 'asterisk') {
      player.学战.能力机制 = text(request.mechanism, '能力介绍');
      player.学战.共通限制 = text(request.cost, '共通限制');
      return state;
    }
    player.伐刀能力 ||= {};
    player.伐刀能力.能力本质 = text(request.mechanism, '能力介绍');
    player.伐刀能力.共通限制 = text(request.cost, '共通限制');
  } else if (['saveSkill', 'deleteSkill'].includes(request.action)) {
    if (!['techniques', 'other'].includes(request.group)) throw new Error('技能类别无效。');
    const ability = resolveMvuWorld(before) === 'asterisk' ? player.学战 : player.伐刀能力;
    const current = request.group === 'techniques' ? ability?.招式 : player.其他能力;
    const originalName = request.originalName;
    if (originalName !== null && (typeof originalName !== 'string' || !Object.hasOwn(current || {}, originalName))) throw new Error('当前回复中已没有该技能，请刷新后重试。');
    if (request.action === 'deleteSkill') {
      if (originalName === null) throw new Error('请先选择要删除的技能。');
      delete current[originalName];
    } else {
      const name = text(request.name, '技能名称').trim();
      if (!name || /[~/]/.test(name) || ['__proto__', 'prototype', 'constructor'].includes(name)) throw new Error('技能名称不能为空，也不能包含 /、~ 或保留键。');
      if (name !== originalName && Object.hasOwn(current || {}, name)) throw new Error('已有同名技能，请编辑已有记录或换个名称。');
      if (!['待确认', '学习中', '已掌握'].includes(request.mastery)) throw new Error('请选择技能掌握状态。');
      const previous = originalName === null ? null : current[originalName];
      const skill = previous && typeof previous === 'object' && !Array.isArray(previous) ? { ...previous } : {};
      skill.说明 = text(request.description, '技能说明');
      skill.条件与代价 = text(request.cost, '条件与代价');
      skill.掌握状态 = request.mastery;
      let records = current;
      if (!records) {
        if (request.group === 'techniques') { if (resolveMvuWorld(before) === 'asterisk') records = player.学战.招式 = {}; else { player.伐刀能力 ||= {}; records = player.伐刀能力.招式 = {}; } }
        else records = player.其他能力 = {};
      }
      if (originalName !== null && originalName !== name) delete records[originalName];
      records[name] = skill;
    }
  } else throw new Error('未知的个人资料操作。');
  return state;
}

function createStateController(adapter) {
  const tokens = new WeakMap();
  async function capture(options = {}) {
    const scope = options.scope || 'full';
    if (!['full', 'story', 'tournament', 'qualification', 'national', 'roster', 'dorm', 'player-profile'].includes(scope)) throw new Error('未知的状态操作范围。');
    const snapshot = await adapter.capture(options);
    if (snapshot.data.stat_data?.系统?.结构版本 === 3) {
      const error = new Error('当前楼层是 v3 档案，请先查看迁移差异并确认升级为 v4。');
      error.code = 'MIGRATION_REQUIRED';
      throw error;
    }
    const state = adapter.validate(cloneState(snapshot.data.stat_data), scope);
    const token = Object.freeze({});
    tokens.set(token, { snapshot, state, scope, done: null, kind: 'state' });
    return { state: cloneState(state), token };
  }
  async function prepareMigration(options = {}) {
    if (typeof adapter.migrate !== 'function') throw new Error('当前运行环境未提供迁移预览，请更新状态服务。');
    const snapshot = await adapter.capture(options);
    const preview = adapter.migrate(cloneState(snapshot.data.stat_data));
    const state = adapter.validate(cloneState(preview.state));
    const token = Object.freeze({});
    tokens.set(token, { snapshot, state, scope: 'full', done: null, kind: 'migration' });
    return { ...cloneState(preview), state: cloneState(state), token };
  }
  function assertReplacementScope(snapshot) {
    if (typeof adapter.assertOpeningReplacement !== 'function') throw new Error('当前状态服务不能核对开局替换范围，请更新状态控制器后重试。');
    // 范围验证必须同步完成，临写检查与宿主赋值之间不能让出执行权。
    const result = adapter.assertOpeningReplacement(snapshot);
    if (result && typeof result.then === 'function') throw new Error('开局替换需要同步宿主校验，尚未写入。');
  }
  async function commit(token, build, kind = 'state', openingReplacement = false, operationScope = 'full', assertWritable) {
    const record = tokens.get(token);
    if (!record) throw new Error('操作凭据已失效，请重新读取当前分支。');
    if (record.kind !== kind) throw new Error('操作凭据用途不符；迁移必须通过明确的升级操作提交。');
    if (operationScope !== 'full' && record.scope !== 'full' && record.scope !== operationScope) throw new Error('操作范围已变化，请重新读取后再执行。');
    const scope = operationScope === 'full' ? 'full' : record.scope;
    if (record.busy) throw new Error('正在写入，请勿重复操作。');
    record.busy = true;
    try {
      const checkWritable = () => {
        if (assertWritable && assertWritable()?.then) throw new Error('写入前检查必须同步完成。');
      };
      checkWritable();
      if (openingReplacement) assertReplacementScope(record.snapshot);
      const candidate = adapter.validate(build(cloneState(record.state)), scope);
      if (record.done) {
        if (stateKey(candidate) !== stateKey(record.done)) throw new Error('同一凭据只能重试原操作，请重新读取后再执行新操作。');
        const now = await adapter.current(record.snapshot);
        if (openingReplacement) assertReplacementScope(record.snapshot);
        if (stateKey(adapter.validate(now.data.stat_data, scope)) !== stateKey(record.done)) throw new Error('当前状态已变化，请刷新。');
        return { state: cloneState(record.done), alreadyApplied: true };
      }
      const current = await adapter.current(record.snapshot);
      if (openingReplacement) assertReplacementScope(record.snapshot);
      // API 返回异常但写入已落地时，仅确认匹配结果，绝不再写一遍。
      if (current.data.stat_data?.系统?.结构版本 === 4 && stateKey(adapter.validate(current.data.stat_data, scope)) === stateKey(candidate)) {
        record.done = candidate;
        record.doneScope = scope;
        record.openingReplacement = openingReplacement;
        return { state: cloneState(candidate), alreadyApplied: true };
      }
      if (stateKey(current.data) !== stateKey(record.snapshot.data)) throw new Error('变量已被其他操作更新，请重新读取，草稿已保留。');
      if (openingReplacement) assertReplacementScope(record.snapshot);
      checkWritable();
      await adapter.write(record.snapshot, current.data, candidate, { openingReplacement });
      const persisted = await adapter.current(record.snapshot);
      if (openingReplacement) assertReplacementScope(record.snapshot);
      const result = adapter.validate(persisted.data.stat_data, scope);
      if (stateKey(result) !== stateKey(candidate)) throw new Error('回读与提交内容不一致，未确认写入成功；请检查 MVU 通知后刷新。');
      record.done = result;
      record.doneScope = scope;
      record.openingReplacement = openingReplacement;
      return { state: cloneState(result) };
    } finally { record.busy = false; }
  }
  return Object.freeze({
    version: '4.0.0', get catalogue() { return cloneState(STORY_VOLUMES); }, capture, prepareMigration,
    capabilities: Object.freeze({ scheduleAndRoster: true, rosterPermanentRemoval: true, ocPlayerEditing: true,
      tournament: 'T01', tournamentEngine: 'T02', nativeMvu: 'N01' }),
    get growthRules() { return cloneState(GROWTH_RULES); },
    tournamentView: state => deriveTournament(requireRakudaiState(state)),
    nationalTournamentView: state => deriveNationalTournament(requireRakudaiState(state)),
    isHagunAffiliation,
    shouldInjectTournament: state => resolveMvuWorld(state) === 'rakudai' && shouldInjectTournament(state),
    shouldInjectNationalTournament: state => resolveMvuWorld(state) === 'rakudai' && shouldInjectNationalTournament(state),
    setDorm: (token, active) => commit(token, state => {
      if (resolveMvuWorld(state) !== 'rakudai') throw new Error('当前作品未启用落第宿舍操作。');
      if (typeof active !== 'boolean' || state.系统.开局状态 !== '已建档') throw new Error('请先完成建档，再进入宿舍。');
      return { ...state, 场景: { ...state.场景, 宿舍: active } };
    }, 'state', false, 'dorm'),
    tournamentAction: (token, request) => commit(token, state => { if (resolveMvuWorld(state) !== 'rakudai') throw new Error('当前作品未启用落第赛事操作。'); return prepareTournamentAction(state, request); }, 'state', false, request?.action === 'upsertQualification' ? 'qualification' : ['upsertNationalMatch', 'upsertNationalAdvancement', 'setNationalSchedule'].includes(request?.action) ? 'national' : 'tournament'),
    tournamentOpponents: (state, options) => suggestTournamentOpponents(requireRakudaiState(state), options),
    tournamentParticipant: (state, options) => createTournamentParticipant(requireRakudaiState(state), options),
    commitMigration: token => commit(token, state => state, 'migration'),
    verify: async token => {
      const record = tokens.get(token);
      if (!record?.done) throw new Error('尚无已回读确认的建档结果。');
      const now = await adapter.current(record.snapshot);
      if (record.openingReplacement) assertReplacementScope(record.snapshot);
      const state = adapter.validate(now.data.stat_data, record.doneScope);
      if (stateKey(state) !== stateKey(record.done)) throw new Error('本局状态已变化，请刷新后继续。');
      return { state: cloneState(state) };
    },
    commitOpening: (token, payload) => commit(token, state => applyOpening(state, payload)),
    replaceOpening: (token, payload) => commit(token, state => applyOpeningReplacement(state, payload), 'state', true),
    transition: (token, request) => commit(token, state => applyTransition(state, request), 'state', false, 'story'),
    editPlayerProfile: (token, request, assertWritable) => commit(token, state => editOcPlayerProfile(state, request), 'state', false, 'player-profile', assertWritable),
    setRosterHidden: (token, name, hidden) => commit(token, state => {
      if (typeof name !== 'string' || !name.trim() || /[~/]/.test(name) ||
          ['__proto__', 'prototype', 'constructor'].includes(name) || typeof hidden !== 'boolean') throw new Error('名册操作参数不合法。');
      if (state.系统.开局状态 !== '已建档' || !Object.hasOwn(state.人际, name)) throw new Error('当前分支没有该人物档案，请刷新名册。');
      if (!state.人际[name] || typeof state.人际[name] !== 'object' || Array.isArray(state.人际[name])) throw new Error('该人物资料不是对象，无法修改显示状态。');
      state.人际[name].名册隐藏 = hidden;
      return state;
    }, 'state', false, 'roster'),
    deleteRosterPerson: (token, name) => commit(token, state => {
      if (typeof name !== 'string' || !name.trim() || /[~/]/.test(name) ||
          ['__proto__', 'prototype', 'constructor'].includes(name)) throw new Error('人物名称不合法。');
      if (state.系统.开局状态 !== '已建档' || !Object.hasOwn(state.人际, name)) throw new Error('当前回复页没有该人物资料，请刷新名册。');
      delete state.人际[name];
      state.系统.已删除人物 = [...new Set([...(state.系统.已删除人物 || []), name])];
      return state;
    }, 'state', false, 'roster'),
  });
}

// 开局页与终端共用的本机、当前聊天显示配置；不读取或写入 MVU。
function normalizePlayerPortraitName(value) {
  return typeof value === 'string' ? value.normalize('NFKC').replace(/[\s·・･‧•．.]/g, '').toLowerCase() : '';
}

function safePlayerPortraitName(value) {
  return typeof value === 'string' && value.trim().length > 0 && Array.from(value.trim()).length <= 64 &&
    !/[\x00-\x1f\x7f<>"&{}:：\u2028\u2029]/.test(value);
}

function validatePlayerPortraitUrl(value) {
  if (typeof value !== 'string') throw new Error('头像地址须为文字。');
  value = value.trim();
  if (!value) return '';
  const data = /^data:image\/(png|jpeg|webp|gif);base64,([A-Za-z0-9+/]+={0,2})$/.exec(value);
  if (data) {
    const base64 = data[2], padding = (base64.match(/=+$/) || [''])[0].length;
    if (base64.length % 4 || base64.length * 3 / 4 - padding > 1024 * 1024) throw new Error('本地头像须为 1 MiB 以内的 PNG、JPEG、WebP 或 GIF。');
    return value;
  }
  let url;
  try { url = new URL(value); } catch (_) { throw new Error('请填写有效的 HTTPS 图片地址，或选择本地图片。'); }
  if (url.protocol !== 'https:' || url.username || url.password || /[\x00-\x1f\x7f]/.test(value)) {
    throw new Error('远程头像只接受不含账号密码的 HTTPS 图片地址。');
  }
  return url.href;
}

function validatePlayerDisplayAliases(value) {
  if (!Array.isArray(value) || value.length > 20) throw new Error('别名须为至多 20 个名称。');
  const seen = new Set();
  return value.map(name => {
    if (!safePlayerPortraitName(name)) throw new Error('别名须为 1—64 字的单行名称，不含冒号、引号或标签。');
    return name.trim();
  }).filter(name => { const key = normalizePlayerPortraitName(name); if (seen.has(key)) return false; seen.add(key); return true; });
}

function playerDisplayScope(ctx) {
  const chatId = ctx?.getCurrentChatId?.() ?? ctx?.chatId;
  if (!ctx || chatId === undefined || chatId === null || String(chatId).trim() === '') {
    throw new Error('当前聊天标识尚未就绪，不能读取或保存 OC 外观。');
  }
  return JSON.stringify([ctx.characterId ?? null, ctx.groupId ?? null, String(chatId)]);
}

function createPlayerDisplayStore({ storage, getContext, onChange = () => {} }) {
  const prefix = 'rk:oc:portrait:v1:';
  const own = (value, key) => Object.prototype.hasOwnProperty.call(value, key);
  function profileName(value) {
    if (typeof value !== 'string' || (value.trim() && !safePlayerPortraitName(value))) {
      throw new Error('开局玩家姓名须为空或 1—64 字的安全单行名称。');
    }
    return value.trim();
  }
  function source(value) {
    if (value !== '' && value !== 'opening') throw new Error('头像来源须为空或 opening。');
    return value;
  }
  function read() {
    const scope = playerDisplayScope(getContext()), key = prefix + scope, raw = storage.getItem(key);
    let record;
    if (raw === null) record = { version: 1, avatarUrl: '', aliases: [], revision: 'empty', profileName: '', source: '' };
    else {
      try { record = JSON.parse(raw); } catch (_) { throw new Error('本聊天 OC 外观配置无法读取。'); }
      if (!record || Array.isArray(record) || record.version !== 1) throw new Error('本聊天 OC 外观配置版本不受支持。');
      record = { ...record, avatarUrl: validatePlayerPortraitUrl(record.avatarUrl), aliases: validatePlayerDisplayAliases(record.aliases),
        revision: typeof record.revision === 'string' ? record.revision : raw,
        profileName: record.profileName === undefined ? '' : profileName(record.profileName),
        source: record.source === undefined ? '' : source(record.source) };
    }
    const snapshot = { version: 1, scope, avatarUrl: record.avatarUrl, aliases: record.aliases,
      revision: record.revision, profileName: record.profileName, source: record.source };
    return { key, raw, record, snapshot };
  }
  function get() { return read().snapshot; }
  function save(expected, values) {
    const current = read();
    if (!expected || expected.scope !== current.snapshot.scope || expected.revision !== current.snapshot.revision) {
      throw new Error('聊天或头像设置已变化，请重新读取后保存。');
    }
    if (!values || typeof values !== 'object' || Array.isArray(values)) throw new Error('头像设置须为对象。');
    const changes = {};
    if (own(values, 'avatarUrl')) changes.avatarUrl = validatePlayerPortraitUrl(values.avatarUrl);
    if (own(values, 'aliases')) changes.aliases = validatePlayerDisplayAliases(values.aliases);
    if (own(values, 'profileName')) changes.profileName = profileName(values.profileName);
    if (own(values, 'source')) changes.source = source(values.source);
    const record = { ...current.record, ...changes, version: 1,
      revision: Date.now().toString(36) + '-' + Math.random().toString(36).slice(2) };
    const raw = JSON.stringify(record);
    if (playerDisplayScope(getContext()) !== current.snapshot.scope || storage.getItem(current.key) !== current.raw) {
      throw new Error('聊天或头像设置已变化，请重新读取后保存。');
    }
    try { storage.setItem(current.key, raw); } catch (_) { throw new Error('本机未能保存头像设置；请检查存储空间或浏览器权限。'); }
    if (storage.getItem(current.key) !== raw) throw new Error('头像设置保存后回读不一致，请重新读取。');
    const saved = read();
    if (saved.snapshot.scope !== current.snapshot.scope || saved.raw !== raw) {
      throw new Error('头像设置在保存后又发生变化，请重新读取。');
    }
    onChange(saved.snapshot);
    return saved.snapshot;
  }
  return { get, save };
}

window.RakudaiMvuNative = { version: "N04", runtime: rakudaiMvuRuntime, prepare: prepareRakudaiNativeMvu, install: installRakudaiNativeMvu };
// 构建时与 schema、纯状态规则一起内联；只在 Tavern Helper 上下文使用。
// 精确接口依据及尚未完成的实机验收见 世界书规则/MVU/v4_使用与迁移.md。
(function installRakudaiController() {
  const W = window;
  function host() {
    // Helper 给每个 iframe 都提供 SillyTavern getter，不能据此把自己当成宿主。
    // 每次访问单独捕获跨源异常，优先实际最外层同源酒馆窗口。
    for (const resolve of [() => W.top, () => W.parent, () => W]) {
      try { const candidate = resolve(); if (candidate?.SillyTavern?.getContext) return candidate; } catch (_) {}
    }
    throw new Error('未连接 SillyTavern，档案仅为草稿。');
  }
  function helper(name) {
    if (typeof W[name] === 'function') return W[name].bind(W);
    if (typeof W.TavernHelper?.[name] === 'function') return W.TavernHelper[name].bind(W.TavernHelper);
    throw new Error(`酒馆助手缺少 ${name}，尚未写入。`);
  }
  function validationZ() {
    const Z = W.z || host().z;
    if (!Z?.preprocess || !Z?.toJSONSchema) throw new Error('未找到酒馆助手提供的 Zod 4，尚未写入。');
    return Z;
  }
  function checkHelperVersion() {
    const version = sync(helper('getTavernHelperVersion')(), '读取酒馆助手版本');
    const parts = String(version).match(/^(\d+)\.(\d+)\.(\d+)/);
    if (!parts || Number(parts[1]) < 4 || (Number(parts[1]) === 4 && (Number(parts[2]) < 8 || (Number(parts[2]) === 8 && Number(parts[3]) < 19)))) throw new Error('本建档器需要酒馆助手 4.8.19 或以上的同步变量接口。');
  }
  function runtime() {
    const H = host(), mvu = W.Mvu || H.Mvu;
