      // 轮播数据
      // GA 文库正篇共 19 卷，正式书名只有系列名与卷号，并无独立副标题。
      var NOVEL_COVERS = Array.from({ length: 19 }, function (_, index) {
        var volume = index + 1;
        var originalTitle =
          "落第騎士の英雄譚（キャバルリィ）" + (volume === 1 ? "" : volume);
        return {
          title: "第 " + volume + " 卷 · 落第骑士英雄谭",
