          if(isAsteriskMode())galleryImage.onerror=function(){this.onerror=null;this.src=openingMediaUrl(OPENING_ASTERISK_MEDIA.volumes[0].file);};
          card.addEventListener("click", function (e) {
            e.stopPropagation();
            openCinemaMode(idx);
          });

          track.appendChild(card);
        });

        // 落樱花瓣粒子 (根据屏幕尺寸自适应数量，手机 10 枚，平板 14 枚，电脑 18 枚)
        if (sakuraLayer) {
          sakuraLayer.innerHTML = "";
          var petalCount = isMobile ? 10 : screenW < 1100 ? 14 : 18;
          for (var i = 0; i < petalCount; i++) {
            var petal = document.createElement("div");
