        prepareFinalCard();
        initializeWorldUI();
        var params = new URLSearchParams(window.location.search);
        var sc = parseInt(params.get("scene"), 10);
        if (sc >= 1 && sc <= 3) {
          switchScene(sc);
        } else {
          switchScene(1);
        }
